    public int hauteur() {
        return this.codeTuiles.length;
    }

    public int largeur() {
        return this.codeTuiles[0].length;
    }

    public int codeTuile(int ligne, int col) {
        return codeTuiles[ligne][col];
    }

    public boolean estPraticable(int x, int y) {
        if (x < 0 || x >= largeur() || y < 0 || y >= hauteur()) return false;
        return codeTuiles[y][x] == 1;
    }
